bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
const e=process.env,net=createCreatorTelegramFetch();
const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
try{
const api=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:20000});
const seller=(await pool.query("SELECT seller_user_id FROM videobot_listings WHERE listing_id='v26nov24invoice' AND status='published'")).rows[0];
if(!seller)throw Error('NEW_PUBLICATION_MISSING');
const owner=await createGateOwner({pool,telegramApi:api});
const topic=await owner.getVerifiedVideoTopic({purpose:'video_sale',sellerId:String(seller.seller_user_id),listingId:'v26nov24invoice'});
if(!topic?.verified||topic?.purpose!=='video_sale'||topic?.board!=='video_chat'||!Number.isSafeInteger(topic.chatId))throw Error('TARGET_NOT_VERIFIED');
const identity=await api('getMe',{});
const membership=await api('getChatMember',{chat_id:topic.chatId,user_id:identity.id});
console.log('BOT_MODERATION='+JSON.stringify({status:membership.status,canDelete:membership.can_delete_messages===true,canPost:membership.can_post_messages===true}));
const old=(await pool.query("SELECT r.updated_at,r.status FROM videobot_post_receipts r WHERE r.sale_mode='paid_media' AND r.status='sent' ORDER BY r.updated_at")).rows;
console.log('OLD_POST_AGE='+JSON.stringify({n:old.length,atLeastOneOlderThan48h:old.some(x=>Date.now()-new Date(x.updated_at).getTime()>48*3600*1000)}));
}finally{await net.close();await pool.end();}
NODE
